        isRest = true;
        duration += 1;
        while (musicString.length > duration && musicString[duration] == '-') {
          duration++;
        }
        return;
      }
    } else {
      duration += 1;
      while (musicString.length > duration && musicString[duration] == musicString[duration-1]) {
        duration++;
      }
    }
  }

  List<int> result = [];
