int fruitDistribution(String s, int n) {
  if (n == 0 || s.isEmpty) return 0;

  List<String> fruits = s.split(' ');
  int totalFruits = fruits.length;

  // Calculate the number of people who can get at least one piece
  int minPeople = max(1, totalFruits - n + 1);

  // If there are not enough pieces for everyone to have at least one,
  // then it's impossible and we return -1.
  if (minPeople > n) return -1;

  // The remaining pieces after giving each person a piece
  int extraPieces = n - minPeople;

  // Distribute the extra pieces evenly among all people
  int extraPerPerson = extraPieces ~/ n;
  int remainder = extraPieces % n;

  // Each person gets extraPerPerson + 1 if they're in the first remainder positions
  int maxExtra = extraPerPerson + (remainder != 0 ? 1 : 0);

  return maxExtra;
}

