  if (n == 0) return 0;

  List<int> prefixSum = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefixSum[i + 1] = prefixSum[i] + arr[i];
  }

  int minDifference = 999999999;

  for (int i = 0; i <= n; i++) {
    int leftSum = prefixSum[i];
    int rightSum = prefixSum[n] - leftSum;

    // Compute the absolute difference between the two halves
    int diff = abs(leftSum - rightSum);

    // Update minimum difference if current is smaller
    if (diff < minDifference) {
      minDifference = diff;
    }
  }

  return minDifference;
}

