}

// Partition function using Lomuto's partition scheme
int _partition(List<int> arr, int low, int high) {
  Random random = Random();
  int index = random.nextInt(high - low + 1) + low;
  int pivotValue = arr[index];

  // Move pivot to end of list
  arr.swap(index, high);
  int i = low;
  for (int j = low; j < high; ++j) {
    if (arr[j] < pivotValue) {
      arr.swap(i++, j);
    }
  }
  arr.swap(i, high);
  return i;
}

