  final List<String> factorsN = factorize(n);

  if (factorsX.length == 0 || factorsN.length == 0) return false;

  for (int i = 0; i < min(factorsX.length, factorsN.length); ++i) {
    final String fx = factorsX[i];
    final String fn = factorsN[i];

    if (!fx.endsWith('1') && !fn.endsWith('1')) continue;

    int countF = 0;
    while (countF < factorsX.length && factorsX[countF] == fx) countF++;
    int countFn = 0;
    while (countFn < factorsN.length && factorsN[countFn] == fn) countFn++;

