List<String> factorize(String s) {
  List<String> result = [];

  // Factor out powers of 2 first
  int powerOfTwo = 0;
  while (s.length % 2 == 0) {
    powerOfTwo += 1;
    s = s.replaceAll("2", "");
  }
  if (powerOfTwo > 0) {
    result.add("2^$powerOfTwo");
  }

  // Then check for other primes in order.
  for (var prime in [3,5,7,11,13,17]) {
    int power = 0;
    while (s.length % prime == 0) {
      power += 1;
      s = s.replaceAll(prime.toString(), '');
    }
    if (power > 0) {
      result.add("$prime^$power");
    }
  }

  // Any remaining digits are non-primes or not factored yet. 
  // For simplicity we just add them as a single term.
  if (s.isNotEmpty) {
    result.add(s);
  }

  return result;
}

