    String extName = parts[1];
    // Calculate score based on length and commonality
    int baseScore = extName.length * 50; // More characters mean higher priority
    double frequencyFactor = 1.0 / extensions.where((e) => e.endsWith('.' + extName)).length.toDouble();
    int finalScore = (baseScore * frequencyFactor).round();

    extensionScores[ext] = finalScore;
  }

  if (extensionScores.isEmpty) return 'none';

  var sortedExtensions = extensionScores.entries.toList()
      .sorted((a, b) => b.value.compareTo(a.value));

  var maxScore = sortedExtensions.first.value;
  var candidates = sortedExtensions
      .where((entry) => entry.value == maxScore)
      .map((entry) => entry.key);

  var mostCommon = candidates.reduce((prev, curr) {
    var prevCount = extensions.count((e) => e.endsWith(prev.substring(1)));
    var currCount = extensions.count((e) => e.endsWith(curr.substring(1)));
    return prevCount > currCount ? prev : curr;
  });

  return mostCommon;
}

